import React from 'react';
import { Message, KnowledgeItem, SimilarQuestion } from '../types';

interface ChatMessageProps {
  message: Message;
  knowledgeSources?: KnowledgeItem[];
  onSimilarQuestionClick?: (question: string) => void;
}

export const ChatMessage: React.FC<ChatMessageProps> = ({
  message,
  knowledgeSources,
  onSimilarQuestionClick
}) => {
  return (
    <div className={`message ${message.type}`}>
      <div className="message-content">
        {message.content}

        {knowledgeSources && knowledgeSources.length > 0 && (
          <div className="knowledge-sources">
            <h4>📚 参考知识</h4>
            {knowledgeSources.map((item, idx) => (
              <div key={idx} className="knowledge-item">
                <div className="knowledge-question">{item.question}</div>
                <div className="knowledge-answer">{item.answer}</div>
              </div>
            ))}
          </div>
        )}

        {message.similarQuestions && message.similarQuestions.length > 0 && (
          <div className="similar-questions">
            <h4>💡 相似问题</h4>
            {message.similarQuestions.map((item, idx) => (
              <div
                key={idx}
                className="similar-question-item"
                onClick={() => onSimilarQuestionClick?.(item.question)}
              >
                <div className="question-text">{item.question}</div>
                <div className="keywords">{item.keywords}</div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};
